{
 "stablehlo_contract": [
  {
   "operation": "Program structure and types",
   "syntax": [
    {
     "id": "MOD.SYN.1",
     "rule": "program := `func.func @main(%arg: T, ...) -> T_out { op* ; return %v : T_out }`; each %name defined once"
    },
    {
     "id": "MOD.SYN.2",
     "rule": "op := `%r = \"stablehlo.NAME\"(operands) {attrs}? : (operand_types) -> result_type`"
    },
    {
     "id": "MOD.SYN.3",
     "rule": "int_list_attr := `array<i64: d0, d1, ...>`; int_attr := `N : i64`"
    }
   ],
   "type": [
    {
     "id": "MOD.TYP.1",
     "rule": "T := `tensor<d0 x ... x elem>`; scalar := `tensor<elem>`; elem ∈ {f32, i32, i64, i1}"
    }
   ],
   "semantics": [
    {
     "id": "MOD.SEM.1",
     "rule": "∀ op: no implicit broadcast; no implicit type promotion"
    }
   ]
  },
  {
   "operation": "stablehlo.broadcast_in_dim",
   "syntax": [
    {
     "id": "BID.SYN.1",
     "rule": "`%r = \"stablehlo.broadcast_in_dim\"(%x) {broadcast_dimensions = array<i64: ...>} : (T_in) -> T_out`"
    }
   ],
   "type": [
    {
     "id": "BID.TYP.1",
     "rule": "element_type(result) = element_type(operand)"
    }
   ],
   "shape": [
    {
     "id": "BID.SHP.1",
     "rule": "size(broadcast_dimensions) = rank(operand)"
    },
    {
     "id": "BID.SHP.2",
     "rule": "0 <= broadcast_dimensions < rank(result) ∧ is_unique(broadcast_dimensions)"
    },
    {
     "id": "BID.SHP.3",
     "rule": "∀d: dim(operand,d) = 1 ∨ dim(operand,d) = dim(result, broadcast_dimensions[d])"
    }
   ],
   "semantics": [
    {
     "id": "BID.SEM.1",
     "rule": "result[i] = operand[j], j[d] = (dim(operand,d) = 1 ? 0 : i[broadcast_dimensions[d]])"
    }
   ]
  },
  {
   "operation": "Element-wise operations",
   "syntax": [
    {
     "id": "ELT.SYN.1",
     "rule": "binary := `%r = stablehlo.{add|subtract|multiply|divide|maximum|minimum} %a, %b : T`; unary := `%r = stablehlo.{exponential|negate|sqrt|rsqrt|abs} %a : T`"
    }
   ],
   "type": [
    {
     "id": "ELT.TYP.1",
     "rule": "element_type(lhs) = element_type(rhs) = element_type(result)"
    }
   ],
   "shape": [
    {
     "id": "ELT.SHP.1",
     "rule": "shape(lhs) = shape(rhs) = shape(result)"
    }
   ],
   "semantics": [
    {
     "id": "ELT.SEM.1",
     "rule": "divide(int): trunc toward 0; {exponential, sqrt, rsqrt}: is_float(element_type)"
    }
   ]
  }
 ]
}
